import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>

#define TILE 32

__global__ void triu_matmul_kernel(const float* __restrict__ A,
                                   const float* __restrict__ B,
                                   float* __restrict__ C,
                                   int n) {
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int bx = blockIdx.x;
    const int by = blockIdx.y;

    const int row = by * TILE + ty;
    const int col = bx * TILE + tx;

    // Blocks entirely below the diagonal only need to write zeros.
    if (by > bx) {
        if (row < n && col < n) {
            C[(long)row * n + col] = 0.0f;
        }
        return;
    }

    float acc = 0.0f;

    // For upper-triangular A and B, an output tile (by, bx) only needs
    // K tiles in the inclusive range [by, bx].
    for (int kt = by; kt <= bx; ++kt) {
        const int a_col = kt * TILE + tx;
        const int b_row = kt * TILE + ty;

        As[ty][tx] = (row < n && a_col < n) ? A[(long)row * n + a_col] : 0.0f;
        Bs[ty][tx] = (b_row < n && col < n) ? B[(long)b_row * n + col] : 0.0f;

        __syncthreads();

#pragma unroll
        for (int k = 0; k < TILE; ++k) {
            acc += As[ty][k] * Bs[k][tx];
        }

        __syncthreads();
    }

    if (row < n && col < n) {
        C[(long)row * n + col] = (row <= col) ? acc : 0.0f;
    }
}

torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32 &&
                B.scalar_type() == torch::kFloat32,
                "A and B must be float32");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(A.size(0) == A.size(1) &&
                B.size(0) == B.size(1) &&
                A.size(0) == B.size(0),
                "A and B must be square matrices with the same shape");

    auto Ac = A.contiguous();
    auto Bc = B.contiguous();
    auto C = torch::empty_like(Ac);

    const int n = Ac.size(0);
    dim3 threads(TILE, TILE);
    dim3 blocks((n + TILE - 1) / TILE, (n + TILE - 1) / TILE);

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    triu_matmul_kernel<<<blocks, threads, 0, stream>>>(
        Ac.data_ptr<float>(),
        Bc.data_ptr<float>(),
        C.data_ptr<float>(),
        n
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();

    return C;
}
"""

_cpp_src = "torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B);"

_mod = load_inline(
    name="triu_matmul_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["triu_matmul_cuda"],
    verbose=False,
    extra_cuda_cflags=["-O3", "--use_fast_math"],
)


class ModelNew(nn.Module):
    """
    CUDA implementation of C = triu(A @ B) for upper-triangular matrices.
    """

    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A, B):
        if not A.is_cuda:
            A = A.cuda()
        if not B.is_cuda:
            B = B.cuda()
        return _mod.triu_matmul_cuda(A, B)

